import{_ as r,l as c,o as a,c as i,v as t,p as d,x as s,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"套接字缓冲与背压","description":"","frontmatter":{"title":"套接字缓冲与背压","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/socket-buffers.md","filePath":"cs/socket-buffers.md","lastUpdated":1789023840000}'),m={name:"cs/socket-buffers.md"};function _(h,e,f,u,A,E){const o=c("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="套接字缓冲与背压" tabindex="-1">套接字缓冲与背压 <a class="header-anchor" href="#套接字缓冲与背压" aria-label="Permalink to &quot;套接字缓冲与背压&quot;">​</a></h1><div class="epigraph"><p>每个 sock 有接收与发送内存会计：队列里的 sk_buff 计入 rmem/wmem，满了就对应用或对 TCP 窗口施压，而不是在网卡上无限堆。</p><footer>—— 据 POSIX SO_RCVBUF/SO_SNDBUF；Linux 对 sk_buff 会计与 tcp_mem 的说明；Stevens, <em>UNP</em></footer></div><p><a href="/cs/tx-path-qdisc">上一课</a>会在 qdisc 丢包。<a href="/cs/rx-path">RX</a> 会把 skb 挂进 sk。缺口是 <strong>套接字缓冲</strong>：谁付钱、何时 <code>EAGAIN</code>、TCP 窗口如何跟着变。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读者慢，内核若无限排队，内存被一个连接吃光。<code>sk_rmem_alloc</code> 超 <code>sk_rcvbuf</code> 则 drop 或缩小窗口。发送：未确认数据占 <code>sk_wmem</code>，满则 <code>send</code> 阻塞或 EAGAIN。缺口：自动调优（tcp_moderate_rcvbuf）；cgroup 的 memory 与 net 会计交叉；UDP 无窗口，只能丢。本课不把每条 sysctl 当考纲。</p><p><span class="marginnote">SO_SNDBUF 是提示，内核常加倍记账。unix 域套接字也有类似缓冲，不经 qdisc。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>recv</code>：从 sk 队列剥 skb，拷到用户（或 zerocopy），减会计，可能发窗口更新。<code>send</code>：分配 skb，会计加，进 TCP 发送队列，再走 TX。对照 <a href="/cs/page-cache">页缓存</a>：文件脏页有 writeback；套接字没有盘，只有对端 ACK 或本地读。对照 blkio：那是块设备，这里是字节流内存。</p>',8)),(a(),d(p,null,{default:s(()=>[n(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RX%5B%22%E5%85%A5%E5%8C%85%22%5D%20--%3E%20RMEM%5B%22%E8%AE%A1%E5%85%A5%20rcvbuf%22%5D%0A%20%20RMEM%20--%3E%7C%22%E6%BB%A1%22%7C%20BACK%5B%22%E4%B8%A2%E6%88%96%E7%BC%A9%E7%AA%97%E5%8F%A3%22%5D%0A%20%20SND%5B%22send%22%5D%20--%3E%20WMEM%5B%22%E8%AE%A1%E5%85%A5%20sndbuf%22%5D%0A%20%20WMEM%20--%3E%7C%22%E6%BB%A1%22%7C%20BLK%5B%22%E9%98%BB%E5%A1%9E%E6%88%96%20EAGAIN%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>背压把端到端的「谁更快」收成内核计数器，保护主机。TCP 把接收缓冲翻译成通告窗口，于是慢读者压住快写者——这是传输课在 OS 里的落点。不要写成量化订单流控。</p><p>与 <a href="/cs/napi">NAPI</a>：NAPI 配额是 CPU 时间；rmem 是内存。两者都会 drop，原因不同。</p><p>实现上：tcp_rmem 三元组是自动调优的范围，SO_RCVBUF 会关掉自动。内存压力下 tcp_mem 进入压力档，强制缩小窗口。unix 套接字的缓冲是内核内存，也进 memcg。 读法上只引用<a href="/cs/tx-path-qdisc">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>套接字缓冲与背压</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>tcp_notsent_lowat</code> 的全部应用调优。不保证 RDMA 的 QP 缓冲走同一会计。下一课把 TCP 状态机在内核里的要点钉住，而不重开拥塞控制数学全文。</p><p>版本字段会变，课序钉的是机制对象「套接字缓冲与背压」，不是某一主线内核的结构体名。 后课默认：套接字有内存上限并反向施压。内核 TCP 实现的队列与定时器要点，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>rcv/snd 缓冲会计限制每连接内存。</li><li>满则丢、缩窗口或阻塞应用。</li><li>内核 TCP 要点是下一课。</li><li>出处：Stevens <em>UNP</em>；Linux tcp；POSIX socket 选项。</li></ul>',11))])}const b=r(m,[["render",_]]);export{P as __pageData,b as default};
